package com.brandempiricism.etocrm.platform.tenancy;
import java.security.Principal;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/platform/tenants")class TenantProvisioningController{private final TenantProvisioningService tenants;private final TenantProvisioningWorkflow workflow;TenantProvisioningController(TenantProvisioningService tenants,TenantProvisioningWorkflow workflow){this.tenants=tenants;this.workflow=workflow;}@GetMapping List<TenantProvisioningService.TenantView> list(){return tenants.list();}@GetMapping("/{id}")TenantProvisioningService.TenantView get(@PathVariable UUID id){return tenants.get(id);}@PostMapping @ResponseStatus(HttpStatus.ACCEPTED)TenantProvisioningService.TenantView register(@RequestBody TenantProvisioningService.RegisterTenant request,Principal principal){return tenants.register(request,principal.getName());}@PostMapping("/{id}/provision") @ResponseStatus(HttpStatus.ACCEPTED)TenantProvisioningService.TenantView provision(@PathVariable UUID id,Principal principal){return workflow.provision(id,principal.getName());}}
